package hu.synostream.android;
import android.content.*;import android.app.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.util.*;
@RunWith(AndroidJUnit4.class) public class Android057Test {
 final Android050FlowTest f=new Android050FlowTest();String homePackage;
 @Before public void init()throws Exception{f.instrumentation=InstrumentationRegistry.getInstrumentation();f.context=f.instrumentation.getTargetContext();f.app=(SynoApp)f.context.getApplicationContext();f.device=UiDevice.getInstance(f.instrumentation);UiLocale.save(f.context,"hu");f.device.wakeUp();f.device.executeShellCommand("wm dismiss-keyguard");f.device.pressHome();f.device.waitForIdle();homePackage=f.device.getCurrentPackageName();assertNotEquals(f.pkg,homePackage);}
 @After public void cleanup()throws Exception{UiLocale.save(f.context,"hu");f.instrumentation.runOnMainSync(()->{f.app.cancelScan();f.app.epoch++;f.app.torrentDraft.close();f.app.externalTorrentUri=null;f.app.externalTorrentMime=null;});f.cleanup();}
 void setup(FakeNas n)throws Exception{f.setup(n,List.of(new Library.Card("/Movies/Demo.Movie.2020.mkv","Visszalépési próba",true)));f.instrumentation.waitForIdleSync();}
 void outside()throws Exception{assertTrue("Back must expose the observed launcher "+homePackage+", current="+f.device.getCurrentPackageName(),f.device.wait(Until.hasObject(By.pkg(homePackage).depth(0)),10000));assertNotEquals(f.pkg,f.device.getCurrentPackageName());}
 void reopen(){f.context.startActivity(new Intent(f.context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/menu_button")),10000));}
 @Test public void backButtonFromMovieRootLeavesTaskAndKeepsSession()throws Exception{try(FakeNas n=new FakeNas()){setup(n);MainActivity before=f.activity();NasClient client=f.app.client;f.device.pressBack();outside();assertFalse(before.isFinishing());assertSame(client,f.app.client);assertEquals(1,f.app.cards.size());reopen();assertTrue(f.device.hasObject(By.desc("Visszalépési próba")));}}
 @Test public void backGestureFromEnglishShowsRootLeavesTask()throws Exception{try(FakeNas n=new FakeNas()){setup(n);UiLocale.save(f.context,"en");MainActivity before=f.activity();f.instrumentation.runOnMainSync(()->{f.app.page="shows";f.app.selectedLibrary=LibraryConfig.defaultLibrary(f.app.libraries,false).optString("id");before.recreate();});assertTrue(f.device.wait(Until.hasObject(By.text("TV shows")),10000));assertEquals("Gestural navigation required for gesture regression","2",f.device.executeShellCommand("settings get secure navigation_mode").trim());f.device.swipe(2,f.device.getDisplayHeight()/2,f.device.getDisplayWidth()/2,f.device.getDisplayHeight()/2,25);outside();assertNotNull(f.app.client);reopen();assertTrue(f.device.hasObject(By.text("TV shows")));}}
 @Test public void drawerClosesBeforeRootBackLeaves()throws Exception{try(FakeNas n=new FakeNas()){setup(n);f.click("menu_button");assertTrue(f.device.wait(Until.hasObject(By.text("Kijelentkezés")),10000));f.device.pressBack();Thread.sleep(400);assertEquals(f.pkg,f.device.getCurrentPackageName());f.device.pressBack();outside();}}
 @Test public void settingsReturnsToLibraryBeforeRootBackLeaves()throws Exception{try(FakeNas n=new FakeNas()){setup(n);f.click("menu_button");f.text("Beállítások");assertTrue(f.device.wait(Until.hasObject(By.text("Nyelv: Magyar")),10000));f.device.pressBack();assertTrue(f.device.wait(Until.hasObject(By.text("Filmek")),10000));assertEquals(f.pkg,f.device.getCurrentPackageName());f.device.pressBack();outside();}}
 @Test public void searchAndKeyboardAreDismissedBeforeLeaving()throws Exception{try(FakeNas n=new FakeNas()){setup(n);assertTrue(f.device.wait(Until.hasObject(By.desc("Keresés")),10000));f.device.findObject(By.desc("Keresés")).click();assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/search_box")),10000));f.device.findObject(By.res(f.pkg+":id/search_box")).click();f.device.findObject(By.res(f.pkg+":id/search_box")).setText("próba");for(int attempt=0;attempt<3&&f.device.hasObject(By.res(f.pkg+":id/search_box"));attempt++){f.device.pressBack();Thread.sleep(350);}assertFalse(f.device.hasObject(By.res(f.pkg+":id/search_box")));assertEquals(f.pkg,f.device.getCurrentPackageName());f.device.pressBack();outside();}}
 @Test public void detailAndAboutBackDoNotPrematurelyLeaveApp()throws Exception{try(FakeNas n=new FakeNas()){setup(n);assertTrue(f.device.wait(Until.hasObject(By.desc("Visszalépési próba")),10000));f.device.findObject(By.desc("Visszalépési próba")).click();assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/detail_info")),10000));f.device.pressBack();assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/menu_button")),10000));assertEquals(f.pkg,f.device.getCurrentPackageName());MainActivity a=f.activity();f.instrumentation.runOnMainSync(()->AboutUi.show(a,"about"));assertTrue(f.device.wait(Until.hasObject(By.text("Verzió: "+BuildConfig.VERSION_NAME)),10000));f.device.pressBack();assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/menu_button")),10000));assertEquals(f.pkg,f.device.getCurrentPackageName());f.device.pressBack();outside();}}
 @Test public void logoutFromSettingsDoesNotTrapLoginBack()throws Exception{try(FakeNas n=new FakeNas()){setup(n);f.click("menu_button");f.text("Beállítások");f.click("menu_button");f.text("Kijelentkezés");assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/login_button")),10000));assertNull(f.app.client);f.device.pressBack();if(f.pkg.equals(f.device.getCurrentPackageName())){Thread.sleep(400);f.device.pressBack();}outside();}}
 @Test public void rootBackKeepsBackgroundScanRunning()throws Exception{try(FakeNas n=new FakeNas()){setup(n);n.holdListResponse=true;try{f.click("refresh_button");assertTrue("Background NAS list reached",n.listRequestRead.await(8,java.util.concurrent.TimeUnit.SECONDS));assertTrue("Scan active before Back",f.app.scanRunning);f.device.pressBack();outside();assertTrue("Scan stays active while NAS response is held",f.app.scanRunning);assertNotNull(f.app.client);reopen();assertTrue("Returning to the task does not cancel scan",f.app.scanRunning);n.releaseListResponse.countDown();long end=System.currentTimeMillis()+15000;while(f.app.scanRunning&&System.currentTimeMillis()<end)Thread.sleep(50);assertFalse("Scan finishes after NAS response is released",f.app.scanRunning);assertEquals(2,f.app.cards.size());}finally{n.releaseListResponse.countDown();}}}
 @Test public void rootBackKeepsExternalPlayerStreamAlive()throws Exception{try(FakeNas n=new FakeNas()){setup(n);f.device.executeShellCommand("pm grant "+f.pkg+" android.permission.POST_NOTIFICATIONS");f.context.startForegroundService(new Intent(f.context,StreamService.class).putExtra("path","/Movies/Demo.Movie.2020.mkv"));long end=System.currentTimeMillis()+7000;while(StreamService.readyUri==null&&System.currentTimeMillis()<end)Thread.sleep(50);assertNotNull(StreamService.readyUri);android.net.Uri before=StreamService.readyUri;f.device.pressBack();outside();assertEquals(before,StreamService.readyUri);assertNotNull(f.app.client);reopen();assertEquals(before,StreamService.readyUri);}}
}
